<div class="system-grid">
<?php foreach ($recipes as $recipe): ?>
<article class="system-card"><div class="card-top"><span class="eyebrow">RECETA · V<?= e($recipe['version']) ?></span><?php if ($recipe['archived_at']): ?><span class="badge">Eliminada</span><?php endif ?></div><span class="badge"><?= $recipe['source_kind'] === 'afec' ? 'Observación AFEC' : ($recipe['source_kind'] === 'community' ? 'Referencia comunitaria' : 'Plantilla manual') ?></span><?php if ($recipe['source_kind'] !== 'manual' && $recipe['version'] !== '1'): ?><span class="badge">Ajustada localmente</span><?php endif ?><h2><?= e($recipe['name']) ?></h2><p class="muted"><?= e($recipe['type']) ?><?= $recipe['tier'] ? ' · ' . e($recipe['tier']) : ' · Tier sin confirmar' ?> · <?= e($recipe['material_count']) ?> materiales</p><p class="recipe-help muted"><?= e($recipe['source_note']) ?></p><?php if ($recipe['source_url']): ?><a class="back-link" href="<?= e($recipe['source_url']) ?>" target="_blank" rel="noopener noreferrer">Consultar fuente ↗</a><?php endif ?>
<div class="card-actions">
<?php if (!$recipe['archived_at']): ?><button type="button" class="button-quiet" data-action="recipe-edit" data-record="<?= record_attribute($recipe) ?>">Editar receta y materiales</button><?php endif ?>
<button type="button" class="button-quiet <?= !$recipe['archived_at'] ? 'button-danger' : '' ?>" data-action="<?= $recipe['archived_at'] ? 'recipe-restore' : 'recipe-archive' ?>" data-record="<?= record_attribute($recipe) ?>"><?= $recipe['archived_at'] ? 'Restaurar receta' : 'Eliminar receta' ?></button>
<button type="button" class="button-quiet" data-action="history" data-record="<?= record_attribute(['type' => 'facility_recipe', 'id' => $recipe['id']]) ?>">Ver cambios</button>
</div></article>
<?php endforeach ?>
</div><?php endif ?>
